// Le topic est de la forme: iot/{did}/operational/request
// msg.payload contient le corps JSON envoyé par le dispositif
const topicParts = msg.topic.split('/');
if (topicParts.length < 4) {
    node.warn('[Parser] Topic malformé ignoré : ' + msg.topic);
    return null;
}

const didFromTopic = topicParts[1];

let body;
try {
    body = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.warn('[Parser] Payload JSON invalide pour did=' + didFromTopic + ' : ' + e.message);
    return null;
}

msg.did              = didFromTopic;
msg.jwt              = body.jwt;
msg.timestamp        = body.timestamp;
msg.proofSignature   = body.proofSignature;
msg.requestedPermission = body.requestedPermission || null;

// Clé Redis du cache device
msg.redisKey = 'device:' + didFromTopic;

return msg;

// Bug 2 fix : connexion Redis persistante initialisée une seule fois dans
// l'onglet 'On Start' pour éviter la création/destruction à chaque message.
const redis = context.get('redisClient');
if (!redis) {
    node.warn('[Cache] Client Redis non initialisé — retrying...');
    msg.cacheHit = false;
    return msg;
}

try {
    const data = await redis.hgetall(msg.redisKey);

    // Bug 3 fix : forcer un booléen pour que le Switch fonctionne correctement.
    // hgetall retourne null si la clé n'existe pas — sans le !! le switch perd
    // le message quand data === null (ni true ni false en Node-RED).
    msg.cache    = data || {};
    msg.cacheHit = !!(data && Object.keys(data).length > 0);
} catch (e) {
    node.warn('[Cache] Erreur Redis pour did=' + msg.did + ' : ' + e.message);
    msg.cache    = {};
    msg.cacheHit = false;
}

return msg;

