// Bug 2 fix : créer la connexion Redis une seule fois au démarrage du nœud.
// Dans Node-RED, require() n'est pas disponible dans initialize —
// on utilise le module déclaré dans 'libs' (var: Redis, module: ioredis).
const client = new Redis({
    host: 'host.docker.internal',
    port: 6379,
    lazyConnect: false,
    retryStrategy: (times) => Math.min(times * 100, 3000)
});
client.on('error', (err) => node.warn('[Cache] Redis error: ' + err.message));
client.on('ready', ()    => node.log('[Cache] Redis connecté'));
context.set('redisClient', client);

finalize:
// Fermer proprement la connexion quand le nœud est arrêté
const redis = context.get('redisClient');
if (redis) {
    redis.disconnect();
    context.set('redisClient', null);
}

