// ─────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────

function base32Decode(str) {
    const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
    let bits = 0, value = 0;
    const output = [];
    for (const char of str.toUpperCase()) {
        const idx = alphabet.indexOf(char);
        if (idx === -1) continue;
        value = (value << 5) | idx;
        bits += 5;
        if (bits >= 8) {
            output.push((value >>> (bits - 8)) & 0xFF);
            bits -= 8;
        }
    }
    return Buffer.from(output);
}

// base64url sans padding → Buffer
function base64UrlDecode(str) {
    let s = str.replace(/-/g, '+').replace(/_/g, '/');
    while (s.length % 4) s += '=';
    return Buffer.from(s, 'base64');
}

// base64 standard (utilisé pour cnf.jwk.x dans le JWT)
function base64Decode(str) {
    return Buffer.from(str, 'base64');
}

function decodeJwtPayload(jwt) {
    const parts = jwt.split('.');
    if (parts.length !== 3) throw new Error('Format JWT invalide');
    return JSON.parse(base64UrlDecode(parts[1]).toString('utf8'));
}

function verifyJwtSignature(jwt, issuerPublicKeyBase32) {
    if (!issuerPublicKeyBase32) return false;
    const parts = jwt.split('.');
    if (parts.length !== 3) return false;
    const signingInput  = Buffer.from(parts[0] + '.' + parts[1], 'utf8');
    const signature     = base64UrlDecode(parts[2]);
    const issuerPubKey  = base32Decode(issuerPublicKeyBase32);
    return nacl.sign.detached.verify(signingInput, signature, issuerPubKey);
}

function sameBytes(a, b) {
    return a.length === b.length && a.every((v, i) => v === b[i]);
}

// Bug 5 fix : lire le secret depuis process.env (variable système Docker)
// et non via env.get() qui lit les variables du nœud Node-RED uniquement.
function buildLogMsg(did, authorized, reason, requestedPermission, violationType) {
    return {
        payload: {
            did,
            authorized,
            reason:              reason || null,
            requestedPermission: requestedPermission || null,
            violationType:       violationType || null
        },
        headers: {
            'Content-Type':    'application/json',
            'X-Gateway-Secret': process.env.GATEWAY_SHARED_SECRET || ''
        }
    };
}

// ─────────────────────────────────────────────────────────────────────────
// Vérification principale
// ─────────────────────────────────────────────────────────────────────────

try {
    msg.topic = 'iot/' + msg.did + '/operational/response';
    const cache = msg.cache;

    // 1. Signature JWT vérifiée contre la clé publique de l'issuer (admin)
    if (!verifyJwtSignature(msg.jwt, cache.issuerPublicKey)) {
        const reason = 'Signature JWT PoP invalide (cache HIT)';
        msg.payload = { authorized: false, reason };
        return [null, msg, buildLogMsg(msg.did, false, reason, msg.requestedPermission)];
    }

    const claims = decodeJwtPayload(msg.jwt);

    // 2. Le DID du topic MQTT doit correspondre au subject du JWT
    if (claims.sub !== msg.did) {
        const reason = 'DID incohérent entre topic MQTT et JWT (cache HIT)';
        msg.payload = { authorized: false, reason };
        return [null, msg, buildLogMsg(msg.did, false, reason, msg.requestedPermission)];
    }

    // 3. Vérification de l'issuer si présent dans le cache
    if (cache.issuerDid && claims.iss !== cache.issuerDid) {
        const reason = 'Issuer JWT inattendu (cache HIT)';
        msg.payload = { authorized: false, reason };
        return [null, msg, buildLogMsg(msg.did, false, reason, msg.requestedPermission)];
    }

    // 4. La clé publique dans cnf.jwk doit correspondre à celle du cache
    const cnfX = claims.cnf && claims.cnf.jwk && claims.cnf.jwk.x;
    const devicePubKeyBytes = base32Decode(cache.publicKey);
    if (!cnfX || !sameBytes(base64Decode(cnfX), devicePubKeyBytes)) {
        const reason = 'JWT PoP non lié à la clé du dispositif (cache HIT)';
        msg.payload = { authorized: false, reason };
        return [null, msg, buildLogMsg(msg.did, false, reason, msg.requestedPermission)];
    }

    // 5. Expiration du JWT
    const now = Math.floor(Date.now() / 1000);
    if (claims.exp < now) {
        const reason = 'JWT PoP expiré (cache HIT)';
        msg.payload = { authorized: false, reason };
        return [null, msg, buildLogMsg(msg.did, false, reason, msg.requestedPermission)];
    }

    // 6. Fraîcheur du timestamp de la preuve de possession (±30s)
    if (Math.abs(now - msg.timestamp) > 30) {
        const reason = 'Preuve de possession non fraîche (cache HIT)';
        msg.payload = { authorized: false, reason };
        return [null, msg, buildLogMsg(msg.did, false, reason, msg.requestedPermission)];
    }

    // 7. Vérification de la signature de la preuve : sign(jti:timestamp)
    const proofMessage   = Buffer.from(claims.jti + ':' + msg.timestamp, 'utf8');
    const proofSig       = base64UrlDecode(msg.proofSignature);
    if (!nacl.sign.detached.verify(proofMessage, proofSig, devicePubKeyBytes)) {
        const reason = 'Preuve de possession invalide (cache HIT)';
        msg.payload = { authorized: false, reason };
        return [null, msg, buildLogMsg(msg.did, false, reason, msg.requestedPermission)];
    }

    // 8. Vérification de la permission
    const permissions = (cache.permissions || '').split(',').filter(p => p.length > 0);
    if (msg.requestedPermission && !permissions.includes(msg.requestedPermission)) {
        const reason = 'Permission non accordée : ' + msg.requestedPermission;
        msg.payload = { authorized: false, reason };
        return [null, msg, buildLogMsg(msg.did, false, reason, msg.requestedPermission, 'PERMISSION_VIOLATION')];
    }

    // ✅ Autorisé
    msg.payload = {
        authorized:  true,
        did:         msg.did,
        status:      cache.status,
        permissions: permissions
    };
    return [msg, null, buildLogMsg(msg.did, true, null, msg.requestedPermission)];

} catch (e) {
    const reason = 'Erreur de vérification locale (cache HIT) : ' + e.message;
    node.error('[HIT] ' + reason);
    msg.topic   = 'iot/' + msg.did + '/operational/response';
    msg.payload = { authorized: false, reason };
    return [null, msg, buildLogMsg(msg.did, false, reason, msg.requestedPermission)];
}

// Chemin cache MISS : transmettre la requête au backend Spring Boot
msg.payload = {
    did:                 msg.did,
    jwt:                 msg.jwt,
    timestamp:           msg.timestamp,
    proofSignature:      msg.proofSignature,
    requestedPermission: msg.requestedPermission
};
msg.headers = { 'Content-Type': 'application/json' };
return msg;

// Bug 6 fix : msg.did est préservé depuis le parser à travers tout le flow.
// On s'assure tout de même qu'il est présent avant de construire le topic.
if (!msg.did) {
    node.warn('[MISS] msg.did absent à la réponse backend — réponse ignorée');
    return null;
}
msg.topic = 'iot/' + msg.did + '/operational/response';
// msg.payload contient déjà la réponse JSON parsée du backend (authorized, status, permissions, reason)
return msg;
